const items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      error: true,
      error_type: "synthesis_input_error",
      error_message: "No framework evaluation items were received for synthesis."
    }
  }];
}

// Build evaluations array from all framework result items
const evaluations = items.map(item => ({
  framework_name: item.json.framework_name ?? "Unknown Framework",
  framework_evaluation: item.json.framework_evaluation ?? ""
}));

// Build one long text block for the synthesis model
const evaluations_text = evaluations
  .map((ev, index) => {
    return `Framework ${index + 1}: ${ev.framework_name}\n\n${ev.framework_evaluation}`;
  })
  .join("\n\n--------------------\n\n");

return [{
  json: {
    run_id: $('When Executed by Another Workflow').item.json.run_id,
    use_case_name: $('When Executed by Another Workflow').item.json.use_case_name || "Unnamed Use Case",
    use_case_text: $('Extract Text from File').item.json.text || "",
    source_filename: $('When Executed by Another Workflow').item.json.source_filename,
    upload_timestamp: $('When Executed by Another Workflow').item.json.upload_timestamp,
    version_tag: $('When Executed by Another Workflow').item.json.version_tag,
    synthesis_prompt: $input.first().json.synthesis_prompt || "",
    evaluations: evaluations,
    evaluations_text: evaluations_text
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

